export const dict = { id, en };

export function makeT(lang) {
  const d = dict[lang] || dict.id;
  return (key, vars) => {
    let s = d[key] ?? dict.en[key] ?? key;
    if (vars) for (const k of Object.keys(vars)) s = s.replaceAll(`{${k}}`, String(vars[k]));
    return s;
  };
}
export const LANGS = ['id', 'en'];
